{
  "message": "I’m very sorry for your loss. I can help move your flight by two days. To get started, please share the details below.",
  "requests": [
    {
      "field": "user_id",
      "prompt": "What is your user ID?"
    },
    {
      "field": "reservation_id",
      "prompt": "What is your reservation ID?",
      "note": "If you don’t know it, please let me know and I’ll look it up after you provide your user ID."
    },
    {
      "field": "segments_to_change",
      "prompt": "Which part of your trip should be moved by two days: outbound, return, or both?"
    },
    {
      "field": "new_date(s)",
      "prompt": "What is the exact new date for the flight(s) after moving by two days? Please provide YYYY-MM-DD for each affected segment."
    },
    {
      "field": "time_preferences",
      "prompt": "Do you have a preferred departure time window on the new date(s), or should I look at all times?"
    },
    {
      "field": "routing_preferences",
      "prompt": "Are you okay with one-stop flights, or do you prefer direct only?"
    }
  ],
  "note": "Once I pull up your reservation, I’ll verify it’s eligible for a date change and keep the origin, destination, trip type, cabin, and passengers the same. I’ll then share available options and ask for your confirmation before making any changes."
}

